/* data symbols: addresses inside the game data segment (rs_image, see data.c) */
#pragma once
#define RS_IMAGE_BASE 0x08804000u
#ifdef RS_GUEST64
/* 64-bit targets: the image lives in the guest window at its PSP address (copied from rs_image_init, data.c) */
extern u32 rs_image_init[];
#define RS_IMAGE_ARRAY rs_image_init
#define rs_image_w ((u32 *)(rs_gbase + RS_IMAGE_BASE))
#define RS_IMG(o) (RS_IMAGE_BASE + (u32)(o))
#else
extern u32 rs_image_w[];
#define RS_IMAGE_ARRAY rs_image_w
#define RS_IMG(o) ((u32)(uintptr_t)((u8 *)rs_image_w + (o)))
#endif
#define rs_image ((u8 *)rs_image_w)
u32 rs_loadout_table(int);   /* native hook (tools/dc/hooks.py) */
